## Secure Implementation - Actuator Hardening

### Tier 1: Critical Fix (5 minutes) - Disable/Restrict Endpoints

NEVER expose actuator endpoints to the public internet. Restrict exposure to specific trusted endpoints only.

```java
// SecureActuatorApp.java
package com.example.actuator.secure;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.annotation.web.configuration.WebSecurityConfigurerAdapter;
import org.springframework.security.core.userdetails.User;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.security.core.userdetails.UserDetailsService;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.provisioning.InMemoryUserDetailsManager;
import org.springframework.context.annotation.Bean;

// SECURE: Enables Spring Security (not disabled!)
@SpringBootApplication
public class SecureActuatorApp {
    public static void main(String[] args) {
        SpringApplication.run(SecureActuatorApp.class, args);
    }
}

// application.yml (SECURE CONFIGURATION):
/*
spring:
  application:
    name: customer-api

management:
  endpoints:
    web:
      exposure:
        # SECURE: Only expose health to public, others require authentication
        include: health,prometheus  # CRITICAL: Whitelist only necessary endpoints
      # SECURE: Alternative - exclude sensitive endpoints
      # exclude: env,beans,mappings,loggers

  endpoint:
    health:
      show-details: when-authorized  # SECURE: Hide details without auth
    env:
      enabled: false  # SECURE: Disable env endpoint entirely

  # SECURE: Disable dangerous endpoints
  shutdown:
    enabled: false

  # SECURE: Never expose sensitive endpoints
management.endpoints.web.exposure.exclude: "env,beans,loggers,mappings"

# SECURE: Secrets NOT in environment - use external config/vault
spring.config.import: "optional:configserver:http://config-server:8888"
*/

@Configuration
@EnableWebSecurity
public class SecurityConfig extends WebSecurityConfigurerAdapter {

    @Override
    protected void configure(HttpSecurity http) throws Exception {
        http
            // SECURE: Require HTTPS in production
            .requiresChannel()
            .anyRequest()
            .requiresSecure()
            .and()

            // SECURE: Protect actuator endpoints
            .authorizeRequests()
            // SECURE: Health is public (health checks use this)
            .antMatchers("/actuator/health").permitAll()
            // SECURE: Prometheus metrics require authentication
            .antMatchers("/actuator/prometheus").hasRole("METRICS")
            // SECURE: ALL other actuator endpoints require ADMIN
            .antMatchers("/actuator/**").hasRole("ADMIN")
            // SECURE: All business APIs require authentication
            .antMatchers("/api/**").authenticated()
            // SECURE: Public endpoints (login, etc)
            .antMatchers("/public/**", "/login", "/signup").permitAll()
            // SECURE: Deny everything else by default
            .anyRequest().denyAll()
            .and()

            // SECURE: Enable CSRF protection
            .csrf().and()

            // SECURE: Security headers
            .headers()
            .contentSecurityPolicy("default-src 'self'")
            .and()
            .xssProtection()
            .and()
            .frameOptions().deny()
            .and()
            .and()

            // SECURE: HTTP Basic Auth for metrics scraping
            .httpBasic();
    }

    // SECURE: Define users with minimal permissions
    @Bean
    @Override
    public UserDetailsService userDetailsService() {
        UserDetails metricsUser = User.builder()
            .username("metrics_user")
            .password(passwordEncoder().encode("${METRICS_PASSWORD}"))  // From vault/config-server
            .roles("METRICS")
            .build();

        UserDetails adminUser = User.builder()
            .username("admin")
            .password(passwordEncoder().encode("${ADMIN_PASSWORD}")})
            .roles("ADMIN")
            .build();

        return new InMemoryUserDetailsManager(metricsUser, adminUser);
    }

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }
}
```

