### Tier 3: Production Hardening (30 minutes) - Monitoring & Network Control

```java
// SECURE: Network-level access control
/*
Kubernetes NetworkPolicy example:
apiVersion: networking.k8s.io/v1
kind: NetworkPolicy
metadata:
  name: customer-api-netpol
spec:
  podSelector:
    matchLabels:
      app: customer-api
  policyTypes:
  - Ingress
  - Egress
  ingress:
  # Allow traffic from ingress controller only
  - from:
    - podSelector:
        matchLabels:
          app: ingress-nginx
    ports:
    - protocol: TCP
      port: 8080
  # Allow Prometheus scraping from monitoring namespace
  - from:
    - namespaceSelector:
        matchLabels:
          name: monitoring
    ports:
    - protocol: TCP
      port: 8080
      path: /actuator/prometheus
  egress:
  # Allow DNS
  - to:
    - namespaceSelector: {}
      podSelector:
        matchLabels:
          k8s-app: kube-dns
    ports:
    - protocol: UDP
      port: 53
  # Allow database access
  - to:
    - podSelector:
        matchLabels:
          app: postgres
    ports:
    - protocol: TCP
      port: 5432
*/

@Component
public class ActuatorAccessAudit {

    private static final Logger logger = LoggerFactory.getLogger(ActuatorAccessAudit.class);
    private final MeterRegistry meterRegistry;

    public ActuatorAccessAudit(MeterRegistry meterRegistry) {
        this.meterRegistry = meterRegistry;
    }

    @EventListener
    public void onAuthenticationSuccess(AuthenticationSuccessEvent event) {
        String username = event.getAuthentication().getName();

        if (username.equals("metrics_user") || username.equals("admin")) {
            logger.info("Actuator access granted to: {}", username);
            meterRegistry.counter("actuator.access", "user", username).increment();
        }
    }

    @EventListener
    public void onAuthenticationFailure(AuthenticationFailureBadCredentialsEvent event) {
        String username = event.getAuthentication().getName();

        if (username.equals("metrics_user") || username.equals("admin")) {
            logger.warn("SECURITY ALERT: Failed actuator access attempt for: {}", username);
            meterRegistry.counter("actuator.access.failed", "user", username).increment();
        }
    }
}

